/**
 * AttentionHeatmapPremium.js - Color-coded Attention Heatmap
 * With gradient color visualization
 */

import React from 'react';
import { motion } from 'framer-motion';

const AttentionHeatmapPremium = ({ days }) => {
  const maxImportance = Math.max(...days.map(d => d.importance));

  const getHeatColor = (importance) => {
    const normalized = importance / maxImportance;
    if (normalized > 0.7) return '#ef4444'; // Red - High
    if (normalized > 0.4) return '#f59e0b'; // Orange - Medium
    return '#3b82f6'; // Blue - Low
  };

  return (
    <div className="glass-card heatmap-card-premium">
      <h3 className="section-title">
        <span className="icon">👁️</span>
        <span>Important Historical Days</span>
      </h3>

      <div className="heatmap-grid">
        {days.map((day, index) => {
          const percentage = (day.importance / maxImportance) * 100;
          const color = getHeatColor(day.importance);

          return (
            <motion.div
              key={day.day_index}
              className="heatmap-item"
              initial={{ opacity: 0, scale: 0.8 }}
              animate={{ opacity: 1, scale: 1 }}
              transition={{ duration: 0.4, delay: index * 0.1 }}
              whileHover={{ scale: 1.05, y: -5 }}
            >
              <div className="heatmap-rank" style={{ color }}>
                #{index + 1}
              </div>

              <div className="heatmap-info">
                <div className="heatmap-label">
                  {day.days_ago === 0 ? 'Today' : `${day.days_ago} days ago`}
                </div>
                <div className="heatmap-value">
                  Importance: {day.importance.toFixed(3)}
                </div>
              </div>

              <div className="heatmap-visual">
                <motion.div
                  className="heatmap-bar"
                  initial={{ width: 0 }}
                  animate={{ width: `${percentage}%` }}
                  transition={{ duration: 0.8, delay: 0.3 + index * 0.1 }}
                  style={{
                    background: `linear-gradient(90deg, ${color}aa, ${color})`,
                    boxShadow: `0 0 15px ${color}66`,
                  }}
                />
              </div>

              <motion.div
                className="heatmap-dot"
                style={{ background: color }}
                animate={{
                  scale: [1, 1.2, 1],
                  opacity: [0.7, 1, 0.7],
                }}
                transition={{
                  duration: 2,
                  repeat: Infinity,
                  delay: index * 0.3,
                }}
              />
            </motion.div>
          );
        })}
      </div>

      <div className="heatmap-legend">
        <div className="legend-item">
          <div className="legend-dot" style={{ background: '#3b82f6' }} />
          <span>Low Attention</span>
        </div>
        <div className="legend-item">
          <div className="legend-dot" style={{ background: '#f59e0b' }} />
          <span>Medium Attention</span>
        </div>
        <div className="legend-item">
          <div className="legend-dot" style={{ background: '#ef4444' }} />
          <span>High Attention</span>
        </div>
      </div>

      <div className="feature-tip">
        <span className="tip-icon">💡</span>
        <span className="tip-text">
          Model focuses on these days when making predictions
        </span>
      </div>
    </div>
  );
};

export default AttentionHeatmapPremium;
